  3289→// ---- DARK MODE ----
  3290→(function() {
  3291→    const saved = localStorage.getItem('theme') || 'light';
  3292→    document.documentElement.setAttribute('data-theme', saved);
  3293→    updateDarkIcon(saved);
  3294→})();
  3295→
  3296→function toggleDark() {
  3297→    const current = document.documentElement.getAttribute('data-theme');
  3298→    const next    = current === 'dark' ? 'light' : 'dark';
  3299→    document.documentElement.setAttribute('data-theme', next);
  3300→    localStorage.setItem('theme', next);
  3301→    updateDarkIcon(next);
  3302→    document.dispatchEvent(new CustomEvent('themechange', { detail: { theme: next } }));
  3303→}
  3304→
  3305→function updateDarkIcon(theme) {
  3306→    const icon = document.getElementById('darkIcon');
