  3311→// ---- INTERSECTION OBSERVER (fade-up + stagger) ----
  3312→document.addEventListener('DOMContentLoaded', function() {
  3313→    const io = new IntersectionObserver(entries => {
  3314→        entries.forEach(entry => {
  3315→            if (entry.isIntersecting) {
  3316→                entry.target.classList.add('in-view');
  3317→                io.unobserve(entry.target);
  3318→            }
  3319→        });
  3320→    }, { threshold: 0.05 });
  3321→    document.querySelectorAll('.fade-up, .stagger-children').forEach(el => io.observe(el));
  3322→});
