  3324→// ---- MOBILE TABLE ROW-EXPAND ----
  3325→function initMobileRowExpand(scope) {
  3326→    if (window.innerWidth >= 768) return;
  3327→    const root = scope || document;
  3328→    root.querySelectorAll('.table-hover tbody tr:not(.expand-detail-row)').forEach(row => {
  3329→        if (row.querySelector('.mobile-expand-btn')) return; // already initialised
  3330→        const hiddenCells = Array.from(row.querySelectorAll('td')).filter(td =>
  3331→            td.className.includes('d-none') || getComputedStyle(td).display === 'none'
  3332→        );
  3333→        if (!hiddenCells.length) return;
  3334→
  3335→        // Get header labels for the hidden columns
  3336→        const table   = row.closest('table');
  3337→        const headers = table ? Array.from(table.querySelectorAll('thead th')) : [];
  3338→        const allCells = Array.from(row.querySelectorAll('td'));
  3339→
  3340→        // Append expand button inside last cell
  3341→        const lastTd = row.querySelector('td:last-child');
  3342→        if (!lastTd) return;
  3343→        const btn = document.createElement('button');
  3344→        btn.className    = 'mobile-expand-btn';
  3345→        btn.type         = 'button';
  3346→        btn.setAttribute('aria-label', 'Lihat detail');
  3347→        btn.innerHTML    = '<i class="bi bi-chevron-down"></i>';
  3348→        lastTd.appendChild(btn);
  3349→
  3350→        btn.addEventListener('click', function(e) {
  3351→            e.stopPropagation();
  3352→            const open     = this.classList.toggle('open');
  3353→            this.innerHTML = open ? '<i class="bi bi-chevron-up"></i>' : '<i class="bi bi-chevron-down"></i>';
  3354→            this.setAttribute('aria-expanded', open);
  3355→
  3356→            // Remove existing detail row if any
  3357→            const existing = row.nextElementSibling;
  3358→            if (existing && existing.classList.contains('expand-detail-row')) {
  3359→                existing.remove();
  3360→                if (!open) return;
  3361→            }
  3362→
  3363→            // Build detail row
  3364→            const detailRow = document.createElement('tr');
  3365→            detailRow.className = 'expand-detail-row';
  3366→            const td = document.createElement('td');
  3367→            td.colSpan = row.cells.length;
  3368→
  3369→            let innerHtml = '<div class="expand-detail-grid">';
  3370→            hiddenCells.forEach(cell => {
  3371→                const idx   = allCells.indexOf(cell);
  3372→                const label = headers[idx] ? headers[idx].textContent.trim() : '';
  3373→                if (!label || label === '#') return;
  3374→                innerHtml += `<div class="expand-detail-item">
  3375→                    <div class="expand-label">${label}</div>
  3376→                    <div>${cell.innerHTML}</div>
  3377→                </div>`;
  3378→            });
  3379→            innerHtml += '</div>';
  3380→            td.innerHTML = innerHtml;
  3381→            detailRow.appendChild(td);
  3382→            row.after(detailRow);
  3383→        });
  3384→    });
  3385→}
  3386→
  3387→// Run on DOM load for static tables; watch AJAX-populated tbodies
  3388→document.addEventListener('DOMContentLoaded', function() {
  3389→    initMobileRowExpand();
  3390→    if (window.innerWidth < 768) {
  3391→        const obs = new MutationObserver(mutations => {
  3392→            mutations.forEach(m => {
  3393→                if (m.type === 'childList' && m.addedNodes.length) {
  3394→                    const tbody = m.target;
  3395→                    if (tbody.tagName === 'TBODY') {
  3396→                        setTimeout(() => initMobileRowExpand(tbody.closest('table')), 80);
  3397→                    }
  3398→                }
  3399→            });
  3400→        });
  3401→        document.querySelectorAll('tbody').forEach(tb => obs.observe(tb, { childList: true }));
  3402→    }
  3403→});
