  3405→// ---- COUNT-UP ANIMATION ----
  3406→document.addEventListener('DOMContentLoaded', function() {
  3407→    const countEls = document.querySelectorAll('.count-up[data-target]');
  3408→    if (!countEls.length) return;
  3409→    const io2 = new IntersectionObserver(entries => {
  3410→        entries.forEach(entry => {
  3411→            if (!entry.isIntersecting) return;
  3412→            const el = entry.target;
  3413→            const target = parseInt(el.getAttribute('data-target'), 10);
  3414→            if (isNaN(target)) return;
  3415→            const duration = 900;
  3416→            const step = 16;
  3417→            const increment = target / (duration / step);
  3418→            let current = 0;
  3419→            const timer = setInterval(() => {
  3420→                current += increment;
  3421→                if (current >= target) { current = target; clearInterval(timer); }
  3422→                el.textContent = Math.floor(current).toLocaleString('id-ID');
  3423→            }, step);
  3424→            io2.unobserve(el);
  3425→        });
  3426→    }, { threshold: 0.3 });
  3427→    countEls.forEach(el => io2.observe(el));
  3428→});
