  3430→// ---- RIPPLE EFFECT ON ALL BUTTONS ----
  3431→document.addEventListener('click', function(e) {
  3432→    const btn = e.target.closest('.btn');
  3433→    if (!btn) return;
  3434→    const circle = document.createElement('span');
  3435→    const d = Math.max(btn.clientWidth, btn.clientHeight);
  3436→    const r = btn.getBoundingClientRect();
  3437→    circle.className = 'ripple-wave';
  3438→    circle.style.cssText = `width:${d}px;height:${d}px;left:${e.clientX - r.left - d/2}px;top:${e.clientY - r.top - d/2}px`;
  3439→    btn.appendChild(circle);
  3440→    setTimeout(() => circle.remove(), 600);
  3441→});
