  3483→// ---- FORM VALIDATION ENHANCEMENT ----
  3484→document.addEventListener('DOMContentLoaded', function() {
  3485→    // Add real-time validation visual feedback
  3486→    document.querySelectorAll('form .form-control[required], form .form-select[required]').forEach(function(input) {
  3487→        input.addEventListener('blur', function() {
